local function localeKey()
  local preference = type(DpsLabItemScorePreferences) == "table" and DpsLabItemScorePreferences.locale
  if preference == "es" or preference == "en" or preference == "pt" then return preference end
  local locale = type(GetLocale) == "function" and GetLocale() or "enUS"
  if locale == "esES" or locale == "esMX" then return "es" end
  if locale == "ptBR" then return "pt" end
  return "en"
end

catalogs.en.save_profile = "Save profile"
catalogs.es.save_profile = "Guardar perfil"
catalogs.pt.save_profile = "Salvar perfil"

DpsLabLocalization = {
  catalogs = catalogs,
  locale = localeKey,
  Get = function(key)
    local catalog = catalogs[localeKey()]
    return (catalog and catalog[key]) or catalogs.en[key] or nil
  end,
  SetLocale = function(value)
    if value ~= "auto" and value ~= "es" and value ~= "en" and value ~= "pt" then return false end
    DpsLabItemScorePreferences = type(DpsLabItemScorePreferences) == "table" and DpsLabItemScorePreferences or {}
    DpsLabItemScorePreferences.locale = value == "auto" and nil or value
    return true
  end,
}
